mapper.select:
SELECT p.version AS version, p.province_code AS provinceCode, MAX(p.province_name) AS provinceName FROM e_agent_price p WHERE p.del_flag = '0' AND p.version IS NOT NULL AND p.version != ''
AND p.province_code = #{provinceCode}
AND p.version = #{version}
GROUP BY p.version, p.province_code ORDER BY p.version DESC, p.province_code

SELECT d.fpgj_type AS fgvalue, d.biz_time AS bizTime FROM e_fpgj_type t INNER JOIN e_fpgj_type_data d ON t.id = d.en_fpgj_type_id WHERE t.del_flag = '0' AND d.del_flag = '0'
AND t.province_code = #{req.provinceCode}
AND t.second_type = #{req.secondType}
AND t.version = #{req.yearMonth}
ORDER BY d.biz_time

SELECT p.province_code AS provinceCode, MAX(p.province_name) AS provinceName, p.second_type AS secondType, p.third_type AS thirdType FROM e_agent_price p WHERE p.del_flag = '0'
AND p.version = #{version}
GROUP BY p.province_code, p.second_type, p.third_type ORDER BY p.province_code, p.second_type, p.third_type

SELECT DISTINCT p.other_type FROM e_agent_price p WHERE p.del_flag = '0' AND p.other_type IS NOT NULL AND p.other_type != ''
AND p.user_type = #{req.userType}
ORDER BY p.other_type

SELECT DISTINCT p.dy_level FROM e_agent_price p WHERE p.del_flag = '0' AND p.dy_level IS NOT NULL AND p.dy_level != ''
AND p.user_type = #{req.userType}
AND p.other_type = #{req.sfType}
ORDER BY p.dy_level

SELECT d.source_type AS sourceType, d.source_name AS sourceName, d.source_url AS sourceUrl, d.source_file_name AS sourceFileName, d.source_file_hash AS sourceFileHash, d.batch_no AS importBatchNo, d.document_title AS documentTitle, d.document_no AS documentNo, DATE_FORMAT(d.publish_time, '%Y-%m-%d %H:%i:%s') AS publishTime, DATE_FORMAT(d.effective_start, '%Y-%m-%d') AS effectiveStart, DATE_FORMAT(d.effective_end, '%Y-%m-%d') AS effectiveEnd FROM tariff_source_document d WHERE d.status = 'PUBLISHED'
AND d.province_code = #{req.provinceCode}
AND d.version = #{req.yearMonth}
ORDER BY d.publish_time DESC, d.update_time DESC, d.id DESC LIMIT 1

SELECT b.source_type AS sourceType, b.source_name AS sourceName, b.source_url AS sourceUrl, b.source_file_name AS sourceFileName, b.batch_no AS importBatchNo, DATE_FORMAT(b.publish_time, '%Y-%m-%d %H:%i:%s') AS publishTime FROM tariff_import_batch b WHERE 1 = 1
AND b.province_code = #{req.provinceCode}
AND b.version = #{req.yearMonth}
ORDER BY b.publish_time DESC, b.update_time DESC, b.id DESC LIMIT 1

